<?php
require_once __DIR__.'/_init.php';
PA_KasirBridge::ensureTables($pdo);
$title='Ringkasan Multi File';
$token=trim((string)($_GET['token']??''));
if($token===''){ http_response_code(404); exit('Batch tidak ditemukan.'); }
$st=$pdo->prepare('SELECT j.*, pp.* , j.id job_id, pp.name profile_name FROM print_jobs j LEFT JOIN price_profiles pp ON pp.id=j.price_profile_id WHERE j.batch_token=? ORDER BY j.id');
$st->execute([$token]);
$jobs=$st->fetchAll(PDO::FETCH_ASSOC);
if(!$jobs){ http_response_code(404); exit('Batch tidak ditemukan.'); }
$ids=array_map(fn($j)=>(int)$j['job_id'],$jobs);
$summary=['total_pages'=>0,'bw_pages'=>0,'color_25_pages'=>0,'color_50_pages'=>0,'color_75_pages'=>0,'color_100_pages'=>0,'estimated_total'=>0];
$convertedNo='';
foreach($jobs as $j){
    foreach($summary as $k=>$_){ $summary[$k]+=(float)($j[$k]??0); }
    if(!empty($j['no_penjualan'])) $convertedNo=$j['no_penjualan'];
}
$pelanggan=$pdo->query('SELECT kode_pelanggan,nama_pelanggan,no_telepon FROM pelanggan ORDER BY nama_pelanggan LIMIT 800')->fetchAll(PDO::FETCH_ASSOC);
require __DIR__.'/_header.php'; ?>
