<script>
(function(){
 const base=<?= (float)$summary['estimated_total'] ?>, qty=document.getElementById('qtyCetak'), uang=document.getElementById('uangBayar'), totalText=document.getElementById('totalText'), bayarText=document.getElementById('bayarText'), statusText=document.getElementById('statusText'), statusLabel=document.getElementById('statusLabel'), metodeInputs=document.querySelectorAll('input[name="metode"]');
 const rp=n=>'Rp'+Math.round(n).toLocaleString('id-ID');
 function total(){return base*Math.max(1,Number(qty.value||1));}
 function refresh(){const t=total(), b=Number(uang.value||0); totalText.textContent=rp(t); bayarText.textContent=rp(b); if(b>=t){statusLabel.textContent='Kembalian'; statusText.textContent=rp(b-t);}else{statusLabel.textContent='Piutang'; statusText.textContent=rp(t-b);} }
 qty.addEventListener('input',()=>{ if(Number(qty.value)<1) qty.value=1; refresh(); }); uang.addEventListener('input',refresh);
 document.getElementById('qtyMinus').onclick=()=>{qty.value=Math.max(1,Number(qty.value||1)-1); uang.value=Math.round(total()); refresh();};
 document.getElementById('qtyPlus').onclick=()=>{qty.value=Number(qty.value||1)+1; uang.value=Math.round(total()); refresh();};
 document.getElementById('btnLunas').onclick=()=>{ uang.value=Math.round(total()); metodeInputs.forEach(i=>{if(i.value==='Cash')i.checked=true}); refresh(); };
 document.getElementById('btnDp50').onclick=()=>{ uang.value=Math.round(total()/2); refresh(); };
 document.getElementById('btnUtang').onclick=()=>{ uang.value=0; metodeInputs.forEach(i=>{if(i.value==='Utang')i.checked=true}); refresh(); };
 metodeInputs.forEach(i=>i.addEventListener('change',()=>{ if(i.checked && i.value==='Utang'){ uang.value=0; refresh(); } }));
 const search=document.getElementById('customerSearch'), menu=document.getElementById('customerMenu'), hidden=document.getElementById('kodePelangganInput');
 function items(){ return Array.from(menu.querySelectorAll('.pa-customer-item')); }
 function openMenu(){ menu.style.display='block'; filter(); }
 function closeMenu(){ setTimeout(()=>menu.style.display='none',180); }
 function choose(el){ hidden.value=el.dataset.kode; search.value=el.dataset.label; menu.style.display='none'; }
 function filter(){ const q=search.value.toLowerCase().trim(); items().forEach(el=>{ const txt=(el.textContent||'').toLowerCase(); el.style.display=(!q || txt.includes(q))?'block':'none'; }); }
 search.addEventListener('focus',openMenu); search.addEventListener('click',openMenu); search.addEventListener('blur',closeMenu); search.addEventListener('input',()=>{ hidden.value='UMUM'; filter(); openMenu(); });
 items().forEach(el=>el.addEventListener('mousedown',e=>{e.preventDefault(); choose(el);}));
 document.getElementById('kasirForm').addEventListener('submit',function(e){ if(!confirm('Buat satu transaksi kasir dari semua file ini?')) e.preventDefault(); });
 refresh();
})();
</script>
